<script setup>
import {ref,computed,onMounted,nextTick} from 'vue'
import {request} from './client'
import Icon from '../Icon.vue'
import ProviderOverview from './ProviderOverview.vue'
import ProviderMetrics from './ProviderMetrics.vue'
import ClassroomHandovers from './ClassroomHandovers.vue'
import MembershipMail from './MembershipMail.vue'
const props=defineProps({member:Object,institute:Object,teamOnly:Boolean}),emit=defineEmits(['navigate','create','room'])
const instituteTeacher=computed(()=>props.member.institute_teacher===true)
const metricsError=ref(''),teamSection=ref(null)
async function openTeam(){showTeam.value=true;await nextTick();teamSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}
const needsProfile=computed(()=>error.value==='Verify the institute profile first')
const metrics=ref(null),showTeam=ref(false)
const data=ref(null),error=ref(''),busy=ref(false),decision=ref(null)
const admin=computed(()=>props.member.role==='Admin'),pending=computed(()=>data.value?.memberships.filter(l=>l.status==='Pending')||[])
const money=n=>new Intl.NumberFormat('en-LK',{maximumFractionDigits:0}).format(n)
async function load(){error.value='';metricsError.value='';try{data.value=await request('teaching','overview');data.value.memberships.sort((a,b)=>(b.status==='Pending')-(a.status==='Pending'))}catch(e){error.value=e.message;return}try{metrics.value=await request('commercial','metrics')}catch(e){metrics.value=null;metricsError.value='Your teaching overview is ready. Reports could not load. Please try again.'}}
async function act(link,status){busy.value=true;error.value='';try{await request('teaching','membership',{name:link.name,status});decision.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="provider-home"><div class="page-heading"><div><span class="eyebrow">GOOD TEACHING STARTS WITH A LITTLE CLARITY</span><h1>{{teamOnly?'Your teaching team.':admin?institute.title+', together.':'Hello, '+member.full_name.split(' ')[0]+'.'}}</h1><p>{{admin?'Your people, programmes and class fees. All in one place.':instituteTeacher?'Your assigned classes, learners and schedule at '+institute.title+'.':'Your independent classes, learners, schedule and collections.'}}</p></div><button v-if="!teamOnly&&!needsProfile&&!instituteTeacher" class="button primary" @click="emit('create')"><Icon name="Plus" :size="17"/>{{admin?'Create institute class':'Create personal class'}}</button></div><section v-if="needsProfile" class="profile-next-step" role="status"><span class="setup-symbol"><Icon name="Building2" :size="28"/></span><div><span class="eyebrow">LET’S GET YOUR INSTITUTE READY</span><h2>Complete your institute profile</h2><p>Add your institute’s details and submit them for verification. Your teaching overview will be available once the profile is verified.</p><button class="button primary" @click="emit('navigate','profile')">Open institute profile <Icon name="ArrowRight" :size="17"/></button><button class="text-button" @click="load">Check verification status</button></div></section><p v-else-if="error" class="error" role="alert">{{error}}</p><p v-if="!data&&!error">Opening your workspace…</p><template v-if="data"><ClassroomHandovers v-if="admin||instituteTeacher" :admin="admin" @changed="load"/>
<template v-if="!teamOnly"><ProviderOverview :data="data" :metrics="metrics" :admin="admin" :member="member" @navigate="emit('navigate',$event)" @room="emit('room',data.classrooms.find(r=>r.name===$event))" @team="openTeam"/><section v-if="instituteTeacher" class="panel" style="padding:24px;margin-bottom:24px"><h2>Your institute manages the workspace</h2><p>Institute subscriptions and class payments are managed by your institute. Open an assigned classroom to use the teaching tools available to you.</p></section><template v-else><p v-if="metricsError" role="status">{{metricsError}} <button class="text-button" @click="load">Retry reports</button></p><ProviderMetrics v-if="metrics" :source="metrics" :institute="admin"/></template><button class="button subtle team-toggle" @click="showTeam=!showTeam">{{showTeam?'Hide':'Manage'}} {{admin?'teaching team & invitations':'institute memberships'}} <Icon name="ChevronDown" :size="16"/></button></template><div v-if="teamOnly||showTeam" ref="teamSection">
<MembershipMail :member="member" @changed="load"/><div class="section-heading"><div><h2>{{admin?'People who make it happen.':'Your institute memberships.'}}</h2><p>{{admin?'Teachers apply with their own verified account. You choose who joins.':'Keep institute work and personal classes side by side.'}}</p></div><button v-if="!admin" class="button subtle" @click="emit('navigate','connections')">Find an institute</button></div><div class="provider-team"><article v-for="l in data.memberships" :key="l.name" class="panel team-card"><img v-if="l.person?.cover_image" class="team-cover" :src="l.person.cover_image" alt=""><div class="team-content"><img v-if="l.person?.profile_image" :src="l.person.profile_image" class="team-face" alt=""><span class="badge" :class="l.status==='Pending'?'amber':'green'">{{l.status==='Pending'?'Request to join':'Member'}}</span><h3>{{l.person?.display_name||l.user||l.profile}}</h3><p>{{l.person?.qualifications||'Verified education profile'}}</p><small>@{{l.person?.username}}</small><div class="team-actions"><template v-if="admin&&l.status==='Pending'"><button class="button primary small" :disabled="busy" @click="act(l,'Active')">Accept teacher</button><button class="text-button" :disabled="busy" @click="act(l,'Rejected')">Decline</button></template><button v-else class="text-button" @click="decision=l">{{admin?'Remove from institute':'Leave institute'}}</button></div></div></article><p v-if="!data.memberships.length" class="panel empty-mini">Membership requests and approved teachers will appear here.</p></div>
<section v-if="decision" class="panel membership-confirm" role="alert"><h3>{{admin?'Remove teacher membership?':'Leave this institute?'}}</h3><p>This ends access to the institute’s class assignments. The teacher’s account and personal classes remain available.</p><button class="button primary" :disabled="busy" @click="act(decision,admin?'Removed':'Left')">Confirm {{admin?'removal':'leave'}}</button><button class="button subtle" @click="decision=null">Keep membership</button></section>
</div></template></section></template>
<style>.team-toggle{margin:8px 0 24px}.provider-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:26px}.provider-metrics article{padding:24px;display:flex;flex-direction:column;gap:14px}.provider-metrics span{font-size:12px}.provider-metrics strong{font-size:38px;font-weight:650;color:#8163a1}.provider-metrics small{font-size:10px;line-height:1.6;color:var(--student-muted)}.provider-columns{display:grid;grid-template-columns:1.4fr 1fr;gap:24px;margin-bottom:38px}.academy-feature{background:linear-gradient(125deg,rgb(108 106 238 / 8%),rgb(108 106 238 / 12%) 58%,#f4e7ed);border:1px solid rgb(108 106 238 / 12%);border-radius:27px;padding:36px;display:flex;gap:24px;align-items:center;overflow:hidden;color:#554465}.academy-feature h2{font-size:29px;line-height:1.3;margin:18px 0}.academy-feature p{line-height:1.8;font-size:13px;margin-bottom:24px}.programme-art{font-size:80px;display:flex;flex-direction:column;align-items:center;color:#6C6AEE;transform:rotate(-7deg);min-width:120px}.programme-art span{font-family:Georgia,serif;font-size:28px;line-height:1.1;color:#826195}.fee-summary{padding:28px}.fee-summary h2{font-size:22px;margin:15px 0}.fee-summary p{font-size:12px;line-height:1.8;margin-bottom:15px}.fee-total{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--student-border);font-size:12px}.fee-summary .text-button{margin-top:18px}.provider-team{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.team-card{overflow:hidden}.team-cover{width:100%;aspect-ratio:2.8;object-fit:cover}.team-content{padding:0 20px 22px}.team-face{width:70px;height:70px;border:4px solid var(--student-card,#fff);border-radius:50%;object-fit:cover;margin-top:-32px;position:relative;display:block;margin-bottom:12px}.team-content h3{font-size:17px;line-height:1.5;margin:12px 0 7px}.team-content p,.team-content small{font-size:11px;line-height:1.8;color:var(--student-muted)}.team-actions{margin-top:20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.membership-confirm{position:sticky;bottom:20px;padding:25px;box-shadow:0 10px 60px #5e3f6230}.membership-confirm p{margin:16px 0}.membership-confirm button{margin-inline-end:10px}@media(max-width:1150px){.provider-team{grid-template-columns:repeat(3,1fr)}.provider-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.provider-columns{grid-template-columns:1fr}.provider-team{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.provider-team{grid-template-columns:1fr}.provider-metrics article{padding:18px}.academy-feature{padding:26px}.programme-art{display:none}}</style>

<style scoped>.profile-next-step{display:flex;gap:24px;padding:32px;border:1px solid var(--student-border,#e5def0);border-radius:20px;background:var(--student-card,#faf8ff);max-width:900px}.setup-symbol{color:#6c4ba0;background:#eee7fa;border-radius:16px;padding:16px;height:fit-content}.profile-next-step h2{font-size:24px;margin:12px 0}.profile-next-step p{line-height:1.7;margin:0 0 24px;color:var(--student-muted,#655b75)}.profile-next-step button{margin:0 12px 12px 0}@media(max-width:600px){.profile-next-step{padding:24px;flex-direction:column}}</style>
